import { AbstractMessaging } from '@finos/fdc3-agent-proxy';
import { v4 as uuidv4 } from 'uuid';
export class MessagePortMessaging extends AbstractMessaging {
    cd;
    listeners = new Map();
    constructor(cd, appIdentifier) {
        super(appIdentifier);
        this.cd = cd;
        this.cd.messagePort.addEventListener('message', m => {
            this.listeners.forEach(v => {
                if (v.filter(m.data)) {
                    v.action(m.data);
                }
            });
        });
    }
    createUUID() {
        return uuidv4();
    }
    async post(message) {
        this.cd.messagePort.postMessage(message);
        return Promise.resolve();
    }
    register(l) {
        this.listeners.set(l.id, l);
    }
    unregister(id) {
        this.listeners.delete(id);
    }
    createMeta() {
        return {
            requestUuid: this.createUUID(),
            timestamp: new Date(),
            source: super.getAppIdentifier(),
        };
    }
    async disconnect() {
        const bye = {
            type: 'WCP6Goodbye',
            meta: {
                timestamp: new Date(),
            },
        };
        await this.post(bye);
        this.cd.messagePort.close();
    }
}
