import { AgentError } from '@finos/fdc3-standard';
import { Logger } from '../util/Logger.js';
export class AbstractMessaging {
    appIdentifier;
    constructor(appIdentifier) {
        this.appIdentifier = appIdentifier;
    }
    waitFor(filter, timeoutMs, timeoutErrorMessage) {
        const id = this.createUUID();
        return new Promise((resolve, reject) => {
            let done = false;
            let timeout = null;
            const l = {
                id,
                filter: filter,
                action: m => {
                    Logger.debug('Received from DesktopAgent: ', m);
                    done = true;
                    this.unregister(id);
                    if (timeout) {
                        clearTimeout(timeout);
                    }
                    resolve(m);
                },
                register: async () => {
                    this.register(l);
                },
                unsubscribe: async () => {
                    this.unregister(id);
                },
            };
            this.register(l);
            if (timeoutMs) {
                timeout = setTimeout(() => {
                    this.unregister(id);
                    if (!done) {
                        Logger.error(`waitFor rejecting after ${timeoutMs}ms at ${new Date().toISOString()} with ${timeoutErrorMessage}`);
                        reject(new Error(timeoutErrorMessage));
                    }
                }, timeoutMs);
            }
        });
    }
    async exchange(message, expectedTypeName, timeoutMs) {
        const prom = this.waitFor(m => {
            return m.type == expectedTypeName && m.meta.requestUuid == message.meta.requestUuid;
        }, timeoutMs, AgentError.ApiTimeout);
        Logger.debug('Sending to DesktopAgent: ', message);
        this.post(message);
        try {
            const out = await prom;
            if (out?.payload?.error) {
                throw new Error(out.payload.error);
            }
            else {
                return out;
            }
        }
        catch (error) {
            if (error.message == AgentError.ApiTimeout) {
                Logger.error(`Timed-out while waiting for ${expectedTypeName} with requestUuid ${message.meta.requestUuid}`);
            }
            throw error;
        }
    }
    getAppIdentifier() {
        return this.appIdentifier;
    }
}
