import { ChannelError, } from '@finos/fdc3-standard';
import { DefaultContextListener } from '../listeners/DefaultContextListener.js';
import { EventListener } from '../listeners/EventListener.js';
export class DefaultChannel {
    messaging;
    messageExchangeTimeout;
    id;
    type;
    displayMetadata;
    constructor(messaging, messageExchangeTimeout, id, type, displayMetadata) {
        this.messaging = messaging;
        this.messageExchangeTimeout = messageExchangeTimeout;
        this.id = id;
        this.type = type;
        this.displayMetadata = displayMetadata;
        //bind all functions to allow destructuring
        this.broadcast = this.broadcast.bind(this);
        this.getCurrentContext = this.getCurrentContext.bind(this);
        this.addContextListener = this.addContextListener.bind(this);
        this.addEventListener = this.addEventListener.bind(this);
    }
    async broadcast(context, metadata) {
        if (!context || typeof context.type !== 'string') {
            throw new Error(ChannelError.MalformedContext);
        }
        const request = {
            meta: this.messaging.createMeta(),
            payload: {
                channelId: this.id,
                context,
                metadata: metadata ?? {},
            },
            type: 'broadcastRequest',
        };
        await this.messaging.exchange(request, 'broadcastResponse', this.messageExchangeTimeout);
    }
    async getCurrentContext(contextType) {
        // first, ensure channel state is up-to-date
        const request = {
            meta: this.messaging.createMeta(),
            payload: {
                channelId: this.id,
                contextType: contextType ?? null,
            },
            type: 'getCurrentContextRequest',
        };
        const response = await this.messaging.exchange(request, 'getCurrentContextResponse', this.messageExchangeTimeout);
        return response.payload.context ?? null;
    }
    /**
     * Retrieves the current context along with its metadata.
     * Used by the proxy to deliver metadata to context listeners when replaying
     * context after a channel change.
     */
    async getCurrentContextWithMetadata(contextType) {
        const request = {
            meta: this.messaging.createMeta(),
            payload: {
                channelId: this.id,
                contextType: contextType ?? null,
            },
            type: 'getCurrentContextRequest',
        };
        const response = await this.messaging.exchange(request, 'getCurrentContextResponse', this.messageExchangeTimeout);
        const context = response.payload.context;
        if (context) {
            const metadata = {
                source: response.payload.metadata?.source ?? { appId: 'unknown' },
                timestamp: response.payload.metadata?.timestamp ?? response.meta.timestamp,
                traceId: response.payload.metadata?.traceId ?? '',
                signature: response.payload.metadata?.signature,
                custom: response.payload.metadata?.custom,
                antiReplay: response.payload.metadata?.antiReplay,
            };
            return { context, metadata };
        }
        return null;
    }
    async addContextListener(contextType, handler) {
        if (typeof contextType !== 'string' && contextType !== null) {
            throw new Error('Invalid arguments passed to addContextListener!');
        }
        if (typeof handler !== 'function') {
            throw new Error('Invalid arguments passed to addContextListener!');
        }
        return await this.addContextListenerInner(contextType, handler);
    }
    async addContextListenerInner(contextType, theHandler) {
        const listener = new DefaultContextListener(this.messaging, this.messageExchangeTimeout, this.id, contextType, theHandler);
        await listener.register();
        return listener;
    }
    async clearContext(contextType) {
        // first, ensure channel state is up-to-date
        const request = {
            meta: this.messaging.createMeta(),
            payload: {
                channelId: this.id,
                contextType: contextType ?? null,
            },
            type: 'clearContextRequest',
        };
        await this.messaging.exchange(request, 'clearContextResponse', this.messageExchangeTimeout);
    }
    async addEventListener(type, handler) {
        let listener;
        switch (type) {
            case 'contextCleared':
                listener = new EventListener(this.messaging, 'contextCleared', this.id, handler);
                break;
            case null:
                listener = new EventListener(this.messaging, type, this.id, handler);
                break;
            default:
                throw new Error(ChannelError.InvalidArguments);
        }
        await listener.register();
        return listener;
    }
}
